    54  /* Returns a string form of relational operator 'relop'. */
    55  const char *
    56  expr_relop_to_string(enum expr_relop relop)
    57  {
    58      switch (relop) {
    59      case EXPR_R_EQ: return "==";
    60      case EXPR_R_NE: return "!=";
    61      case EXPR_R_LT: return "<";
    62      case EXPR_R_LE: return "<=";
    63      case EXPR_R_GT: return ">";
    64      case EXPR_R_GE: return ">=";
    65      default: OVS_NOT_REACHED();
    66      }
    67  }
