    69  bool
    70  expr_relop_from_token(enum lex_type type, enum expr_relop *relop)
    71  {
    72      enum expr_relop r;
    73
    74      switch ((int) type) {
    75      case LEX_T_EQ: r = EXPR_R_EQ; break;
    76      case LEX_T_NE: r = EXPR_R_NE; break;
    77      case LEX_T_LT: r = EXPR_R_LT; break;
    78      case LEX_T_LE: r = EXPR_R_LE; break;
    79      case LEX_T_GT: r = EXPR_R_GT; break;
    80      case LEX_T_GE: r = EXPR_R_GE; break;
    81      default: return false;
    82      }
    83
    84      if (relop) {
    85          *relop = r;
    86      }
    87      return true;
    88  }
