    90  /* Returns the relational operator that 'relop' becomes if you turn the
    91   * relation's operands around, e.g. EXPR_R_EQ does not change because "a == b"
    92   * and "b == a" are equivalent, but EXPR_R_LE becomes EXPR_R_GE because "a <=
    93   * b" is equivalent to "b >= a". */
    94  static enum expr_relop
    95  expr_relop_turn(enum expr_relop relop)
    96  {
    97      switch (relop) {
    98      case EXPR_R_EQ: return EXPR_R_EQ;
    99      case EXPR_R_NE: return EXPR_R_NE;
   100      case EXPR_R_LT: return EXPR_R_GT;
   101      case EXPR_R_LE: return EXPR_R_GE;
   102      case EXPR_R_GT: return EXPR_R_LT;
   103      case EXPR_R_GE: return EXPR_R_LE;
   104      default: OVS_NOT_REACHED();
   105      }
   106  }
