   108  /* Returns the relational operator that is the opposite of 'relop'. */
   109  static enum expr_relop
   110  expr_relop_invert(enum expr_relop relop)
   111  {
   112      switch (relop) {
   113      case EXPR_R_EQ: return EXPR_R_NE;
   114      case EXPR_R_NE: return EXPR_R_EQ;
   115      case EXPR_R_LT: return EXPR_R_GE;
   116      case EXPR_R_LE: return EXPR_R_GT;
   117      case EXPR_R_GT: return EXPR_R_LE;
   118      case EXPR_R_GE: return EXPR_R_LT;
   119      default: OVS_NOT_REACHED();
   120      }
   121  }
