   123  /* Checks whether 'relop' is true for strcmp()-like 3-way comparison result
   124   * 'cmp'. */
   125  static bool
   126  expr_relop_test(enum expr_relop relop, int cmp)
   127  {
   128      switch (relop) {
   129      case EXPR_R_EQ: return cmp == 0;
   130      case EXPR_R_NE: return cmp != 0;
   131      case EXPR_R_LT: return cmp < 0;
   132      case EXPR_R_LE: return cmp <= 0;
   133      case EXPR_R_GT: return cmp > 0;
   134      case EXPR_R_GE: return cmp >= 0;
   135      default: OVS_NOT_REACHED();
   136      }
   137  }
