   191  static void
   192  expr_insert_andor(struct expr *andor, struct expr *before, struct expr *new)
   193  {
   194      if (new->type == andor->type) {
   195          if (andor->type == EXPR_T_AND) {
   196              /* Conjunction junction, what's your function? */
   197          }
   198          ovs_list_splice(&before->node, new->andor.next, &new->andor);
   199          free(new);
   200      } else {
   201          ovs_list_insert(&before->node, &new->node);
   202      }
   203  }
