   215  static void
   216  expr_not(struct expr *expr)
   217  {
   218      struct expr *sub;
   219
   220      switch (expr->type) {
   221      case EXPR_T_CMP:
   222          expr->cmp.relop = expr_relop_invert(expr->cmp.relop);
   223          break;
   224
   225      case EXPR_T_AND:
   226      case EXPR_T_OR:
   227          LIST_FOR_EACH (sub, node, &expr->andor) {
   228              expr_not(sub);
   229          }
   230          expr->type = expr->type == EXPR_T_AND ? EXPR_T_OR : EXPR_T_AND;
   231          break;
   232
   233      case EXPR_T_BOOLEAN:
   234          expr->boolean = !expr->boolean;
   235          break;
   236
   237      case EXPR_T_CONDITION:
   238          expr->cond.not = !expr->cond.not;
   239          break;
   240
   241      default:
   242          OVS_NOT_REACHED();
   243      }
   244  }
