   246  static struct expr *
   247  expr_fix_andor(struct expr *expr, bool short_circuit)
   248  {
   249      struct expr *sub, *next;
   250
   251      LIST_FOR_EACH_SAFE (sub, next, node, &expr->andor) {
   252          if (sub->type == EXPR_T_BOOLEAN) {
   253              if (sub->boolean == short_circuit) {
   254                  expr_destroy(expr);
   255                  return expr_create_boolean(short_circuit);
   256              } else {
   257                  ovs_list_remove(&sub->node);
   258                  expr_destroy(sub);
   259              }
   260          }
